import TablaConPaginacion from "../../Componentes/TablaConPaginacion/TablaConPaginacion";
import PanelPromociones from "../../Componentes/Paneles/PanelPromociones/PanelPromociones";
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages';
import Pestanias from "../../Componentes/Pestanias/Pestanias";
import Boton from "../../Componentes/Boton/Boton";
import { useState, useEffect, useRef } from 'react';
import columnasCombo from '../../Datos_Pruebas/Columnas_Combo.json';
import columnasDescuento from '../../Datos_Pruebas/Columnas_Descuentos.json';
import Modal from "../../Componentes/Modal/Modal";
import FormularioCombo from "../../Componentes/Formularios/NuevoCombo/FormularioCombo";
import FormularioDescuento from "../../Componentes/Formularios/NuevoDescuento/FormularioDescuento";
import ModificarDescuento from "../../Componentes/Formularios/ModificarDescuento/ModificarDescuento";
import ModificarCombo from "../../Componentes/Formularios/ModificarCombo/ModificarCombo";
import { toast } from "sonner";
import { useForm } from "react-hook-form";
import Input from "../../Componentes/Input/Input";
import Tarjeta from "../../Componentes/ComponentesFormulario/Tarjeta/Tarjeta";
import { useValidarSesion } from "../../hooks/useValidarSesion";



export default function Promociones({ }) {

  //Obtenermos datos del usuario
  const { storeCargado, token, usuario } = useValidarSesion(); // obtener el token desde Zustand



  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE crear descuento/combo y con ello mostrar o no algunas opciones

  const permisoManipularPromo = usuario?.permisos?.some(
    (permiso) => (permiso.nombrePermiso === 'crear descuento' || permiso.nombrePermiso === 'crear combo')
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => (permiso.nombrePermiso === 'crear descuento' || permiso.nombrePermiso === 'crear combo')
    );


  //BOOLEANO DEFINE SI ES SUPERADMIN
  const esSuperAdmin = usuario?.rol?.[0]?.nombreRol === "superadmin";

  //ESTADO PARA DETERMINAR LA SUCURSAL
  const [idSucursalSeleccionada, setIdSucursalSeleccionada] = useState(
    esSuperAdmin ? null : usuario?.sucursal?.[0]?.id_sucursal || null
  );

  //MANEJA CAMBIO DE OFERTAS
  const [ofertaSeleccionada, setOfertaSeleccionada] = useState('Combo'); //Estado que determina si esta seleccionado COMBO o DESCUENTO
  const manejaCambiooferta = (nuevaOferta) => {
    setOfertaSeleccionada(nuevaOferta);
  };

  //MANEJA MODAL DE MODIFICACION 
  const [modalModifOferta, setModifiOferta] = useState(false);  //Estado que controla la visualizacion del modal MODIFICACION  


  const manejaModifiOferta = () => {
    setModifiOferta(!modalModifOferta);

    if (modalModifOferta) {  //si el modal estaba abierto, al cerrarse se setea a null el elmento seleccionado
      setElementoSeleccionado(null);
      actualizarDatos();//acutaliza datos despues de cerrarse el modal
    }
  };

  //MANEJA ELIMINACION DE COMBO O DESCUENTO
  const [modalEliminafOferta, setEliminaOferta] = useState(false);  //Estado que controla la visualizacion del modal ELIMINACION
  const manejaEliminacionOferta = () => {
    setEliminaOferta(!modalEliminafOferta);

    if (modalEliminafOferta) {  //si el modal estaba abierto, al cerrarse se setea a null el elmento seleccionado
      setElementoSeleccionado(null);
      actualizarDatos();//acutaliza datos despues de cerrarse el modal
    }
  }

  //MANEJA NUEVO COMBO O DESCUENTO
  const [modalNuevo, setModalNuevo] = useState(false); //Estado que controla la visualizacion del modal NUEVO COMBO o DESCUENTO

  const manejaModalNuevo = () => {
    setModalNuevo(!modalNuevo);
    if (modalNuevo) {
      actualizarDatos();//acutaliza datos despues de cerrarse el modal
    }
  };

  //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
  const transformaMayusucula = (str) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };


  //MANEJA VISUALIZACION DE COMBOS DESACTIVADOS
  const [verDesactivados, setVerDesactivados] = useState(false); //Estado que controla si se muestran o no los combos desactivados

  //FUNCION PARA RECUPERAR DATOS DE COMBOS DESACTIVADOS
  const [combosDesactivados, setCombosDesactivados] = useState([]);

  // Función para obtener los combos desactivados desde el backend
  const obtenerCombosDesactivados = async () => {
    try {

  const response = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/combo/mostrarDesactivados`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`,

        },
        body: JSON.stringify({ id_sucursal: idSucursalSeleccionada })
      });

      const datos = await response.json();
      const datosTransformados = datos.map(item => ({
        id_combo: item.id_combo,
        Nombre_Combo: transformaMayusucula(item.nombre),
        Descripcion: item.productos,
        Costo_Combo: `$ ${item.costo.replace('.', ',')}`,
        Duracion: new Date(item.duracion).toLocaleDateString()

      }));
      setCombosDesactivados(datosTransformados);
    } catch (error) {
      console.error('Error al obtener combos desactivados:', error);
    }
  };

  // Cuando cambia verDesactivados, si es true, trae los datos
  useEffect(() => {
    if (verDesactivados) {
      obtenerCombosDesactivados();
    }
  }, [verDesactivados]);




  // Función que muestra/oculta el modal
  const manejaVerDesactivados = () => {
    setVerDesactivados(!verDesactivados);
    setElementoSeleccionado(null); // Resetea la selección al cerrar el modal
  }





  /////// FUNCION QUE SE LE PASA AL PANEL PARA RECUPERAR LOS DATOS FILTRADOS DE DESCUENTOS
  const [datosDescuento, setDatosDescuento] = useState([]);
  const obtieneDatosFiltradosDescuento = (datosFiltrados) => {
    setDatosDescuento(datosFiltrados);
  };

  /////// FUNCION QUE SE LE PASA AL PANEL PARA RECUPERAR LOS DATOS FILTRADOS DE COMBOS
  const [datosCombo, setDatosCombo] = useState([]);
  const obtieneDatosFiltradosCombo = (datosFiltrados) => {
    setDatosCombo(datosFiltrados);
  };



  //FUNCION PARA ELIMINAR DESCUENTO


  const eliminaDescuento = async () => {
    setCargando(true);
    const id = elementoSeleccionado.Codigo;

    try {
  const productoUrl = `${import.meta.env.VITE_API_BASE_URL}/api/descuento/${id}`;

      const respuesta = await fetch(productoUrl, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!respuesta.ok) {
        console.error('Error al eliminar el descuento');
        return;
      }

    } catch (error) {
      console.error('Error en la solicitud:', error);
    } finally {
      setCargando(false);
      manejaEliminacionOferta();

    }
  };

  //////METODO QUE DESACTIVA COMBO
  const desactivaCombo = async () => {
    setCargando(true);
    const id = elementoSeleccionado.id_combo;
    try {
  const comboUrl = `${import.meta.env.VITE_API_BASE_URL}/api/combo/${id}/desactivar`;

      const respuesta = await fetch(comboUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`

        }
      });
      if (!respuesta.ok) {
        console.error('Error al desactivar el combo');
        toast.error("Error al desactivar combo.", { className: "__toaster_error" });
        return;
      }
      else {
        console.log('Combo eliminado.');
        toast.success("Combo desactivado.", { className: "__toaster_success" });

      }
    } catch (error) {
      console.error('Error en la solicitud:', error);
    } finally {
      setCargando(false);
      manejaEliminacionOferta();
    }
  };

  /////FUNCION ACTIVA COMBO
  const activaCombo = async (data) => {
    setCargando(true);
    const id = elementoSeleccionado.id_combo;

    try {
  const comboUrl = `${import.meta.env.VITE_API_BASE_URL}/api/combo/${id}/activar`;

      const respuesta = await fetch(comboUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ nuevo_vencimiento: data.nuevo_vencimiento, id_sucursal: idSucursalSeleccionada })
      });

      //Parsear la respuesta JSON para obtener el mensaje
      const datosRespuesta = await respuesta.json();
      if (!respuesta.ok) {
        console.error('Error al activar el combo:', datosRespuesta);

        //  construir mensaje de error detallado
        let mensajeError = datosRespuesta.error || "Error al activar combo.";

        // Si hay detalles (array de productos sin stock), agregarlos al mensaje
        if (datosRespuesta.detalles && Array.isArray(datosRespuesta.detalles)) {
          const detalles = datosRespuesta.detalles
            .map(d => `${transformaMayusucula(d.producto)} (Requerido: ${d.requerido}, Disponible: ${d.disponible})`)
            .join(' | ');
          mensajeError += ` - ${detalles}`;
        }

        toast.error(mensajeError, { className: "__toaster_error" });
        return;
      }
      else {
        toast.success("Combo Activado.", { className: "__toaster_success" });
      }
    } catch (error) {
      console.error('Error en la solicitud:', error);
    } finally {
      setCargando(false);
      actualizarDatos();
    }
  };

  //HOOK FORM
  const { register, handleSubmit, formState: { errors } } = useForm({
  });



  ///////SELECCION DE ELEMENTO GENERAL
  const [elementoSeleccionado, setElementoSeleccionado] = useState(null); //Estado que determina un elemento seleccionado de la tabla

  const manejarSeleccion = (elemento) => {
    setElementoSeleccionado(elemento);
  };


  ///////SELECCION ELEMENTO TIPO DESCUENTO
  const [descuentoSeleccionado, setDescuentoSeleccionado] = useState();

  useEffect(() => {
    if (elementoSeleccionado && ofertaSeleccionada === 'Descuento') {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/descuento/${elementoSeleccionado.Codigo}`)
        .then(respuesta => respuesta.json())
        .then(datos => setDescuentoSeleccionado(datos))
        .catch(e => console.log(e));
    }
  }, [elementoSeleccionado]);//Cuando cambie elementoSeleccionado se ejecuta el efecto


  ///////SELECCION ELEMENTO TIPO COMBO
  const [comboSeleccionado, setComboSeleccionado] = useState();

  useEffect(() => {
    if (elementoSeleccionado && ofertaSeleccionada === 'Combo') {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/combo/${elementoSeleccionado.id_combo}`)
        .then(respuesta => respuesta.json())
        .then(datos => setComboSeleccionado(datos))
        .catch(e => console.log(e));
    }
  }, [elementoSeleccionado]);//Cuando cambie elementoSeleccionado se ejecuta el efecto



  ////ACTUALIZACION DE DATOS USANDO REF PARA INDICARLE AL COMPONENTE DE PANEL PRODUCTOS QUE ACTUALICE LA BUSQUEDA DESPUES DE CADA CRUD

  const panelPromocionesRef = useRef(); // 1º objeto puntero que usamos para acceder al componente HIJO

  const actualizarDatos = () => { // 2º funcion que actualiza los datos
    if (panelPromocionesRef.current) { //current en un principi podria ser null, si no lo esta lo accede
      panelPromocionesRef.current.actualizarDatos();
    }
  };




  /*FLUJO:
  Usuario hace una acción (agregar/modificar/eliminar)
Se cierra el modal
Se llama a actualizarDatos()
actualizarDatos() accede al componente PanelPromociones a través de panelPromocionesRef.current
Se ejecuta el método actualizarDatos definido en PanelPromociones
PanelPromociones obtiene los datos actualizados del backend
Los nuevos datos se muestran en la tabla*/


  /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
  const [cargando, setCargando] = useState(false);
  const manejaCargando = ((valor) => {
    setCargando(valor);
  });

  //  PROTECCIÓN: si todavia no se cargo el store ni usuario, no reendreizar nada
  if (!storeCargado || !usuario || !token) {
    return <div className="__cargando_modal"></div>;
  }



  /////LAYOUT

  const header = <PanelPromociones
    ref={panelPromocionesRef} //3º Se pasa la referencia al componente HIJO. Enlazamos asi el puntero con su hijo
    onTipoOferta={manejaCambiooferta}
    onDatosFiltradosDescuentos={obtieneDatosFiltradosDescuento}
    onDatosFiltradosCombos={obtieneDatosFiltradosCombo}
    onManejaCargando={manejaCargando}
    token={token}
    esSuperAdmin={esSuperAdmin}
    onSeleccionarSucursal={setIdSucursalSeleccionada}
  ></PanelPromociones>


  const main =
    ((ofertaSeleccionada === 'Descuento' && datosDescuento.length === 0) || (ofertaSeleccionada === 'Combo' && datosCombo.length === 0)) ?
      <div style={{ color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '30px' }}>No se encontraron datos</div>
      :
      <TablaConPaginacion
        columnas={ofertaSeleccionada === 'Combo' ? columnasCombo : columnasDescuento}
        datos={ofertaSeleccionada === 'Combo' ? datosCombo : datosDescuento}
        itemsPorPagina={6}
        itemsPorPaginaOpcional
        onElementoSeleccionado={manejarSeleccion}
        cargando={cargando}
      >

      </TablaConPaginacion>

  const navigation = <Pestanias></Pestanias>

  const footer = <div style={{ display: "flex" }}>
    {permisoManipularPromo && <Boton descripcion={"NUEVO"} onClick={manejaModalNuevo} habilitado 
    title={ofertaSeleccionada === 'Combo' ? "Nuevo Combo" : "Nuevo Descuento"}></Boton>}

    <Boton descripcion={"VER"} onClick={manejaModifiOferta} habilitado={elementoSeleccionado}
    title={elementoSeleccionado ? ofertaSeleccionada === 'Combo' ? "Ver combo" : "Ver descuento" : ""}></Boton>
    {permisoManipularPromo && <Boton descripcion={ofertaSeleccionada === 'Combo' ? "DESACTIVAR" : "ELIMINAR"} onClick={manejaEliminacionOferta} habilitado={elementoSeleccionado}
     title={elementoSeleccionado ? ofertaSeleccionada === 'Combo' ? "Desactivar combo" : "Eliminar descuento" : ""}
    ></Boton>}
    {ofertaSeleccionada === 'Combo' ?
      <Boton descripcion={"Mostrar Desactivados"} onClick={manejaVerDesactivados} habilitado title="Moostrar combos desactivados"></Boton> : null}

    {combosDesactivados.length > 0 ?
      (<Modal visible={verDesactivados} titulo={`Combos Desactivados`} funcion={manejaVerDesactivados} anchura={"900px"} altura={"600px"}>

        <TablaConPaginacion
          columnas={columnasCombo}
          datos={combosDesactivados} // Filtra los combos desactivados
          itemsPorPagina={6}
          itemsPorPaginaOpcional
          onElementoSeleccionado={manejarSeleccion}
          cargando={cargando}
        >
        </TablaConPaginacion>

        <form onSubmit={handleSubmit(activaCombo)} className="__formulario_combo"
          style={{
            display: "flex",
            justifyContent: "space-between", // separa a los extremos
            alignItems: "center",             // alinea verticalmente
            marginTop: "25px",
            gap: "20px",
          }}>
          <Boton descripcion={"Activar"} habilitado={elementoSeleccionado} submit title="Reactivar combo" ></Boton>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end" }}>

            <Tarjeta descripcion="Nuevo Vencimiento" forid="nuevo_vencimiento" mensajeError={errors.nuevo_vencimiento?.message}
              style={{ margin: "0 70px 30px 0" }}>
              <Input
              title="Fecha de nuevo vencimiento"
                deshabilitado={!elementoSeleccionado}
                tipo="date"
                id="nuevo_vencimiento"
                {...register("nuevo_vencimiento", {
                  required: { value: true, message: "Ingrese nueva fecha de Vencimiento" },
                  validate: (value) => {
                    const fechaDescuento = new Date(value.replace(/-/g, '/'));
                    const fechaActual = new Date();
                    if (!isNaN(fechaDescuento) && fechaDescuento > fechaActual) return true;
                    else return "Ingrese una fecha posterior al dia de hoy";
                  }
                })}
              />
            </Tarjeta>
          </div>

        </form>



      </Modal>)
      : (<Modal visible={verDesactivados} titulo={`Combos Desactivados`} funcion={manejaVerDesactivados} anchura={"700px"}>
        <div style={{ color: 'black', display: 'flex', margin: '30px', alignItems: 'center', justifyContent: 'center', fontSize: '20px' }}>No hay Combos desactivados en esta Sucursal</div>
      </Modal>)
    }



    <Modal visible={modalNuevo} titulo={`Cargar Nuevo ${ofertaSeleccionada}`} funcion={manejaModalNuevo}
      anchura={ofertaSeleccionada === 'Combo' ? "100rem" : "600px"}
      altura={ofertaSeleccionada === 'Combo' ? "68rem" : ""}

    >
      {ofertaSeleccionada === 'Combo' ? <FormularioCombo onGuardar={manejaModalNuevo} id_sucursal={idSucursalSeleccionada} /> :
        <FormularioDescuento onGuardar={manejaModalNuevo} id_sucursal={idSucursalSeleccionada} />}
    </Modal>

    <Modal visible={modalModifOferta} titulo={`Detalles del ${ofertaSeleccionada}`} funcion={manejaModifiOferta} anchura={ofertaSeleccionada === 'Combo' ? "100rem" : "600px"} >
      {ofertaSeleccionada === 'Combo' ?
        <ModificarCombo autocompletar={comboSeleccionado} onGuardar={manejaModifiOferta} /> :
        <ModificarDescuento autocompletar={descuentoSeleccionado} onGuardar={manejaModifiOferta} />}
    </Modal>

    <Modal visible={modalEliminafOferta} titulo={ofertaSeleccionada === 'Combo' ? "Desactivar Combo?" : "Eliminar Descuento?"} funcion={manejaEliminacionOferta} anchura={"500px"} >
      <div style={{ display: "flex", justifyContent: "space-around" }}>

        <Boton descripcion={ofertaSeleccionada === 'Combo' ? "DESACTIVAR" : "ELIMINAR"} onClick={ofertaSeleccionada === 'Combo' ? desactivaCombo : eliminaDescuento} habilitado></Boton>{/*Solo esta implemetado ELIMIACNION DE DESCUENTO*/}
        <Boton descripcion={"CANCELAR"} onClick={manejaEliminacionOferta} habilitado></Boton>
      </div>
    </Modal>

  </div>

  return <PlantillaPages
    header={header}
    navigation={navigation}
    main={main}
    footer={footer}
    nombreUsuario={usuario?.nombre}
    apellidoUsuario={usuario?.apellido}
    sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
    id_sucursal={idSucursalSeleccionada}
    rol={usuario?.rol?.[0]?.nombreRol}
    esSuperAdmin={esSuperAdmin}
    token={token}
  />;





}