import { set, useForm } from "react-hook-form"
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Input from "../../Input/Input";
import Selector from "../../Selector/Selector";
import Boton from "../../Boton/Boton";
import { useState } from "react";
import TablaConPaginacion from "../../TablaConPaginacion/TablaConPaginacion";
import Modal from "../../Modal/Modal";
import AgregarProducto from "../AgregarProductoCarrito/AgregarProductoCarrito";
import './ModificarCombo.css';
import agregar from '../../../assets/agregar_combo.png'
import quitar from '../../../assets/quitar_combo.png'
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";
import no_encontrado from "../../../assets/no_encontrado.png";

export default function ModificarCombo({ onGuardar, autocompletar }) {


    //Obtenermos datos del usuario
    const { usuario, token } = useValidarSesion(); // obtener el token desde Zustand

    //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE crear combo y con ello mostrar o no algunas opciones
    const permisoModificarCombo = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'crear combo'
    );

    //CONTROLA MODIFICAR
    const [modificar, setModificar] = useState(false); // Estado que Habilita la modificacion del descuento

    const manejaModificacion = () => {
        setModificar(!modificar);
    };


    //  MANEJO DE IMAGEN
    const [imagenActual, setImagenActual] = useState(
    autocompletar.foto_url ? `${import.meta.env.VITE_API_BASE_URL}${autocompletar.foto_url}` : no_encontrado
    );

    const [nuevaImagen, setNuevaImagen] = useState(null);
    const [archivoImagen, setArchivoImagen] = useState(null);
    const [mostrarInputFile, setMostrarInputFile] = useState(false);
    const [imagenEliminada, setImagenEliminada] = useState(false);

    // Manejar seleccion de nueva imagen
    const manejarCambioImagen = (e) => {
        const archivo = e.target.files[0];
        if (archivo) {
            setArchivoImagen(archivo);
            setImagenEliminada(false);
            const reader = new FileReader();
            reader.onloadend = () => {
                setNuevaImagen(reader.result);
            };
            reader.readAsDataURL(archivo);
        }
        setMostrarInputFile(false);
    };

    const activarCambioImagen = () => {
        setMostrarInputFile(true);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(false);
    };

    const cancelarCambioImagen = () => {
        setNuevaImagen(null);
        setArchivoImagen(null);
        setMostrarInputFile(false);
        setImagenEliminada(false);
    };

    const eliminarImagenActual = () => {
        setImagenActual(no_encontrado);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(true);
        setMostrarInputFile(false);
    };



    //MANTIENE ARRAY DE PRODUCTOS Y SU MANEJO
    const [productos, setProductos] = useState(autocompletar.productos);

    //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
    const transformaMayusucula = (str) => {
        return str.replace(/\b\w/g, (char) => char.toUpperCase());
    };


    //HOOK FORM
    const { register, handleSubmit, formState: { errors }, reset } = useForm({
        defaultValues: {
            id_sucursal: usuario.sucursal[0].id_sucursal,
            codigo: transformaMayusucula(autocompletar.codigo),
            nombre: transformaMayusucula(autocompletar.nombre),
            duracion: (autocompletar.duracion).split(' ')[0], //se convierte para separar fecha de hora asi me figura como relleno
            costo: (autocompletar.costo.replace('.', ','))
        }

    });



    //SUBMIT PARA REALIZAR LA ACTUALIZACION
    const onSumbit = async (data) => {
        if (productos.length === 0) {
            alert("No hay productos en el combo");

        }
        else {
            try {
                setCargando(true);
                // ✅ USAR FormData PARA ENVIAR IMAGEN
                const formData = new FormData();
                formData.append('codigo', data.codigo);
                formData.append('nombre', data.nombre);
                formData.append('costo', data.costo);
                formData.append('duracion', data.duracion);
                formData.append('id_sucursal', data.id_sucursal);
                formData.append('productos', JSON.stringify(productos));
                formData.append('_method', 'PUT'); // Simular PUT con POST

                // Agregar nueva imagen si existe
                if (archivoImagen) {
                    formData.append('foto', archivoImagen);
                }

                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/combo/${autocompletar.id_combo}`, {
                    method: 'POST',
                    headers: {
                        'Accept': 'application/json',
                        'Authorization': `Bearer ${token}`
                    },
                    body: formData,
                });

                // Intentamos leer siempre la respuesta (aunque haya error)
                const dataRespuestaCombo = await respuesta.json().catch(() => ({}));

                if (!respuesta.ok) {
                    const mensajeError = dataRespuestaCombo?.error || "Error al crear el Combo.";
                    toast.error(mensajeError, { className: "__toaster_error" });
                    return;
                }

                toast.success("Combo modificado correctamente.", { className: "__toaster_success" });
                setModificar(false);
                onGuardar();

                // Resetear estados de imagen
                if (dataRespuestaCombo?.combo?.foto_url) {
                    setImagenActual(`${import.meta.env.VITE_API_BASE_URL}${dataRespuestaCombo.combo.foto_url}`);
                }
                setNuevaImagen(null);
                setArchivoImagen(null);
                setMostrarInputFile(false);
                setImagenEliminada(false);

            } catch (error) {
                console.error('Error en la solicitud:', error);
                toast.error("Error inesperado al modificar el combo.", { className: "__toaster_error" });
            } finally {
                setCargando(false);
            }

        }

    }

    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
    const [cargando, setCargando] = useState(false);


    //LAYOUT

    return (
        <>
            {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
            <form onSubmit={handleSubmit(onSumbit)} className="__formulario_modificar_combo">
                <div className="__cuerpo_modificar_combo">
                    <div className="__fila1">
                        <Tarjeta descripcion="Codigo" forid="codigo" mensajeError={errors.codigo?.message} >
                            <Input
                            title="Codigo del combo"
                                tipo="text"
                                id="codigo"
                                placeholder="Codigo"
                                deshabilitado={!modificar}
                                {...register("codigo", { required: { value: true, message: "Ingrese un codigo del Combo" } })}
                            />
                        </Tarjeta>

                        <Tarjeta descripcion="Nombre" forid="nombre" mensajeError={errors.nombre?.message}>
                            <Input
                            title="Nombre del combo"
                                tipo="text "
                                id="nombre"
                                placeholder="Nombre del combo"
                                deshabilitado={!modificar}
                                {...register("nombre", { required: { value: true, message: "Ingrese nombre del Combo" } })}
                            > </Input>
                        </Tarjeta>
                        {/* ✅ SECCIÓN DE FOTO ACTUALIZADA (igual que sucursal) */}
                        <Tarjeta descripcion="Foto del Combo">
                            <div className="__contenedor_imagen">
                                {nuevaImagen ? (
                                    // Vista previa de nueva imagen seleccionada
                                    <div className="__preview_imagen" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px' }}>
                                        <img src={nuevaImagen} alt="Nueva preview" style={{ maxWidth: "200px" }} />
                                        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                            <Boton
                                                descripcion="Cancelar"
                                                onClick={cancelarCambioImagen}
                                                habilitado={modificar}
                                            />
                                        </div>
                                    </div>
                                ) : (
                                    // Imagen actual o placeholder
                                    <div className="__preview_imagen_modificar_combo" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px' }}>
                                        <img
                                            src={imagenEliminada ? no_encontrado : imagenActual}
                                            alt="Combo"
                                            style={{ maxWidth: "200px" }}
                                        />

                                        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                            <Boton
                                                descripcion="Cambiar"
                                                onClick={activarCambioImagen}
                                                habilitado={modificar && !mostrarInputFile}
                                            />
                                            <Boton
                                                descripcion="Eliminar"
                                                onClick={eliminarImagenActual}
                                                habilitado={modificar && !imagenEliminada && imagenActual !== no_encontrado && !mostrarInputFile}
                                            />
                                        </div>
                                    </div>
                                )}

                                {/* Input file solo cuando se hace clic en "Cambiar" */}
                                {modificar && mostrarInputFile && (
                                    <div style={{ marginTop: "10px" }}>
                                        <input
                                            type="file"
                                            accept="image/*"
                                            onChange={manejarCambioImagen}
                                        />
                                        <div style={{ marginTop: "10px" }}>
                                            <Boton
                                                descripcion="Cancelar"
                                                onClick={cancelarCambioImagen}
                                                habilitado
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        </Tarjeta>
                    </div>
                    <div className="__productos_combo">
                        <TablaConPaginacion
                            columnas={["producto", "cantidad"]}
                            datos={productos}
                            itemsPorPagina={6}
                        >
                        </TablaConPaginacion>
                    </div>
                    <div className="__fila3">
                        <Tarjeta descripcion="Duracion" forid="duracion_combo" mensajeError={errors.duracion?.message}>
                            <Input
                            title="Fecha de duracion del combo"
                                tipo="date"
                                id="duracion_combo"
                                deshabilitado={!modificar}
                                {...register("duracion", {
                                    required: { value: true, message: "Ingrese fecha limite del descuento" },
                                    validate: (value) => {
                                        const fechaDescuento = new Date(value.replace(/-/g, '/'));
                                        const fechaActual = new Date();
                                        if (!isNaN(fechaDescuento) && fechaDescuento > fechaActual) return true;
                                        else return "Ingrese una fecha posterior al dia de hoy";
                                    }
                                })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Costo" forid="costo" mensajeError={errors.costo?.message}>
                            <Input
                            title="Costo del combo"
                                tipo="costo"
                                id="costo"
                                placeholder="00,00"
                                deshabilitado={!modificar}
                                {...register("costo", {
                                    required: {
                                        value: true,
                                        message: "Ingrese precio del Combo"
                                    },
                                    validate: (value) => { //aqui evaluo con otra forma el patron, ya que debo hacer 2 validaciones
                                        const patron = /^\d+(,\d{1,2})?$/; //para que se respete el ingreso luego de la coma y luego
                                        if (!patron.test(value)) {            //convertir el texto en numero para erificar ques es mayor a cero
                                            return "Valor con 2 decimales luego de la ','";
                                        }
                                        // Reemplaza la coma por un punto y convierte a número
                                        const numericValue = parseFloat(value.replace(',', '.'));
                                        if (numericValue <= 0) {
                                            return "Ingrese un precio positivo";
                                        }
                                        return true;
                                    },
                                })}
                            />
                        </Tarjeta>
                    </div>
                </div>
                <div className="__boton_combo">
                    {permisoModificarCombo && <Boton descripcion='Modificar' habilitado={!modificar} onClick={manejaModificacion}></Boton>}
                    {permisoModificarCombo && <Boton descripcion='Guardar' habilitado={modificar} submit></Boton>}
                </div>
            </form >
        </>
    )
}